#!/bin/sh
# Waits for the config generated by the gateway (from .env / config/users.yml) and runs telemt.
# telemt listens on 127.0.0.1:${MTPROXY_INTERNAL_PORT} only; the gateway forwards FakeTLS
# clients from :443 to it with a PROXY v2 header.
set -e
CONF=/etc/telemt/config.toml

i=0
while [ ! -f "$CONF" ] && [ ! -f /etc/telemt/DISABLED ]; do
  i=$((i+1))
  [ $i -gt 120 ] && { echo "telemt: config not generated by gateway after 120s"; exit 1; }
  sleep 1
done

if [ -f /etc/telemt/DISABLED ]; then
  echo "telemt: MTProxy disabled ($(cat /etc/telemt/DISABLED)). Idle."
  # stay idle but react to the config appearing later (gateway restart with users added)
  while [ -f /etc/telemt/DISABLED ]; do sleep 30; done
fi

echo "telemt: starting with $CONF"
exec telemt run "$CONF" --data-path /etc/telemt
